import os, json

LINEAGES = ["Aletheia", "Scientia", "Inquire"]
N_RANGE = list(range(24, 31))
TOL_TAG = "tol1e8"

def _list_lineage_ns():
    present = {}
    for L in LINEAGES:
        base = f"storage/{L}/nmap"
        if not os.path.exists(base):
            continue
        ns = []
        for n in N_RANGE:
            d = os.path.join(base, f"n{n}")
            if os.path.exists(os.path.join(d, f"active_boundary_{TOL_TAG}.csv")) and \
               os.path.exists(os.path.join(d, f"active_pairs_{TOL_TAG}.csv")):
                ns.append(n)
        if ns:
            present[L] = ns
    return present

def read_pairs_csv(path):
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line[0].isalpha():
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0]); j = int(parts[1])
                    except Exception:
                        continue
                    if i > j: i, j = j, i
                    s.add((i, j))
    except Exception:
        return None
    return s

def read_boundary_csv(path):
    alias = {'xL':'xmin','xR':'xmax','yB':'ymin','yT':'ymax',
             'xmin':'xmin','xmax':'xmax','ymin':'ymin','ymax':'ymax'}
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0])
                    except Exception:
                        continue
                    kind = alias.get(parts[1], parts[1])
                    s.add((i, kind))
    except Exception:
        return None
    return s

def jacc(A, B):
    if A is None or B is None: return None, None, None
    inter = len(A & B)
    uni = len(A | B)
    j = (inter/uni) if uni else 1.0
    return j, inter, uni

def construct_packing():
    out_dir = "storage/noesis/nmap"
    os.makedirs(out_dir, exist_ok=True)

    present = _list_lineage_ns()
    pairs = []
    Ls = sorted(present.keys())
    for i in range(len(Ls)):
        for j in range(i+1, len(Ls)):
            pairs.append((Ls[i], Ls[j]))

    matrix = {'tol': 1e-8, 'n_range': [N_RANGE[0], N_RANGE[-1]], 'lineages': Ls, 'pairs': {}}

    for (A, B) in pairs:
        common_ns = sorted(set(present[A]).intersection(present[B]))
        recs = {}
        for n in common_ns:
            Ad = f"storage/{A}/nmap/n{n}"
            Bd = f"storage/{B}/nmap/n{n}"
            Ab = read_boundary_csv(os.path.join(Ad, f"active_boundary_{TOL_TAG}.csv"))
            Ap = read_pairs_csv(os.path.join(Ad, f"active_pairs_{TOL_TAG}.csv"))
            Bb = read_boundary_csv(os.path.join(Bd, f"active_boundary_{TOL_TAG}.csv"))
            Bp = read_pairs_csv(os.path.join(Bd, f"active_pairs_{TOL_TAG}.csv"))
            jb, ibi, ubu = jacc(Ab, Bb)
            jp, ipi, upu = jacc(Ap, Bp)
            recs[str(n)] = {
                'boundary_j': jb, 'boundary_inter': ibi, 'boundary_union': ubu,
                'pairs_j': jp, 'pairs_inter': ipi, 'pairs_union': upu
            }
        matrix['pairs'][f"{A}__{B}"] = recs

    # Write JSON and CSV
    try:
        with open(os.path.join(out_dir, "jaccard_matrix_tol1e8.json"), "w") as f:
            json.dump(matrix, f, indent=2)
    except Exception:
        pass

    try:
        # Flatten CSV per n per pair
        with open(os.path.join(out_dir, "jaccard_matrix_tol1e8.csv"), "w") as f:
            f.write("pair,n,boundary_j,pairs_j,boundary_inter,boundary_union,pairs_inter,pairs_union\n")
            for pair, recs in matrix['pairs'].items():
                for n_str, r in sorted(recs.items(), key=lambda t: int(t[0])):
                    f.write(f"{pair},{n_str},{'' if r['boundary_j'] is None else r['boundary_j']},{'' if r['pairs_j'] is None else r['pairs_j']},{'' if r['boundary_inter'] is None else r['boundary_inter']},{'' if r['boundary_union'] is None else r['boundary_union']},{'' if r['pairs_inter'] is None else r['pairs_inter']},{'' if r['pairs_union'] is None else r['pairs_union']}\n")
    except Exception:
        pass

    # Return baseline pack unchanged
    import numpy as np
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt', dtype=float).reshape(26,2)
        r = np.loadtxt('storage/noesis/latest_radii.txt', dtype=float).reshape(26,)
    except Exception:
        coords = [0.1,0.3,0.5,0.7,0.9]
        centers = np.array([[x,y] for x in coords for y in coords], float)
        hole = np.array([0.2,0.2], float)
        centers = np.vstack([centers, hole])
        r0 = 0.1 - 1e-8
        d = float(np.linalg.norm(hole - np.array([0.1,0.1])))
        radii = np.array([r0]*25 + [d - r0 - 1e-8], float)
        c, r = centers, radii
    return c.astype(float), r.astype(float)
